window.BOOK={"key":"khaqaniyya","app":"mutoon-khaqaniyya","lsk":"mutoon_khaqaniyya_v1","prefix":"kh_","title":"رائية الخاقاني","sub":"التجويد · أبو مزاحم الخاقاني (ت ٣٢٥هـ) · ٥١ بيتًا","poems":[{"id":"khaqaniyya","title":"رائية الخاقاني","nazim":"أبو مزاحم موسى بن عبيد الله الخاقاني","death":"ت ٣٢٥هـ","meter":"الطويل","source":"المكتبة الشاملة: منظومة أبي مزاحم الخاقاني = رائية الخاقاني في التجويد","srcUrl":"https://ketabonline.com/ar/books/102568","note":"النص المشكول من نشرة «رائية الخاقاني في التجويد» في المكتبة الشاملة (٥١ بيتًا كما نصّ الناظم)، قوبل كلمةً كلمةً بسكربت بنشرة «القصيدة الخاقانية» المضبوطة على نص د. غانم قدوري الحمد وبالأبيات المشروحة في ملتقى أهل التفسير. أُكمل ما تركته النشرة من سكون وحركات من النشرة الثانية، وكل شطر موزون على الطويل.","verses":[["أَقُولُ مَقَالًا مُعْجِبًا لِأُولِي الْحِجْرِ","وَلَا فَخْرَ إِنَّ الْفَخْرَ يَدْعُو إِلَى الْكِبْرِ"],["أُعَلِّمُ فِي الْقَوْلِ التِّلَاوَةَ عَائِذًا","بِمَوْلَايَ مِنْ شَرِّ الْمُبَاهَاةِ وَالْفَخْرِ"],["وَأَسْأَلُهُ عَوْنِي عَلَى مَا نَوَيْتُهُ","وَحِفْظِيَ فِي دِينِي إِلَى مُنْتَهَى عُمْرِي"],["وَأَسْأَلُهُ عَنِّي التَّجَاوُزَ فِي غَدٍ","فَمَا زَالَ ذَا عَفْوٍ جَمِيلٍ وَذَا غَفْرِ"],["أَيَا قَارِئَ الْقُرْآنِ أَحْسِنْ أَدَاءَهُ","يُضَاعِفْ لَكَ اللَّهُ الْجَزِيلَ مِنَ الْأَجْرِ"],["فَمَا كُلُّ مَنْ يَتْلُو الْكِتَابَ يُقِيمُهُ","وَلَا كُلُّ مَنْ فِي النَّاسِ يُقْرِئُهُمْ مُقْرِي"],["وَإِنَّ لَنَا أَخْذَ الْقِرَاءَةِ سُنَّةٌ","عَنِ الْأَوَّلِينَ الْمُقْرِئِينَ ذَوِي السِّتْرِ"],["فَلِلسَّبْعَةِ الْقُرَّاءِ حَقٌّ عَلَى الْوَرَى","لِإِقْرَائِهِمْ قُرْآنَ رَبِّهِمُ الْوِتْرِ"],["فَبِالْحَرَمَيْنِ ابْنُ الْكَثِيرِ وَنَافِعٌ","وَبِالْبَصْرَةِ ابْنٌ لِلْعَلَاءِ أَبُو عَمْرِو"],["وَبِالشَّامِ عَبْدُ اللَّهِ وَهْوَ ابْنُ عَامِرٍ","وَعَاصِمٌ الْكُوفِيُّ وَهْوَ أَبُو بَكْرِ"],["وَحَمْزَةُ أَيْضًا وَالْكِسَائِيُّ بَعْدَهُ","أَخُو الْحِذْقِ بِالْقُرْآنِ وَالنَّحْوِ وَالشِّعْرِ"],["فَذُو الْحِذْقِ مُعْطٍ لِلْحُرُوفِ حُقُوقَهَا","إِذَا رَتَّلَ الْقُرْآنَ أَوْ كَانَ ذَا حَدْرِ"],["وَتَرْتِيلُنَا الْقُرْآنَ أَفْضَلُ لِلَّذِي","أُمِرْنَا بِهِ مِنْ مُكْثِنَا فِيهِ وَالْفِكْرِ"],["وَإِمَّا حَدَرْنَا دَرْسَنَا فَمُرَخَّصٌ","لَنَا فِيهِ إِذْ دِينُ الْعِبَادِ إِلَى الْيُسْرِ"],["أَلَا فَاحْفَظُوا وَصْفِي لَكُمْ مَا اخْتَصَرْتُهُ","لِيَدْرِي بِهِ مَنْ لَمْ يَكُنْ مِنْكُمُ يَدْرِي"],["فَفِي شَرْبَةٍ لَوْ كَانَ عِلْمِي سَقَيْتُكُمْ","وَلَمْ أُخْفِ عَنْكُمْ ذَلِكَ الْعِلْمَ بِالذُّخْرِ"],["فَقَدْ قُلْتُ فِي حُسْنِ الْأَدَاءِ قَصِيدَةً","رَجَوْتُ إِلَهِي أَنْ يَحُطَّ بِهَا وِزْرِي"],["وَأَبْيَاتُهَا خَمْسُونَ بَيْتًا وَوَاحِدٌ","تُنَظَّمُ بَيْتًا بَعْدَ بَيْتٍ عَلَى الْإِثْرِ"],["وَبِاللَّهِ تَوْفِيقِي وَأَجْرِي عَلَيْهِ فِي","إِقَامَتِنَا إِعْرَابَ آيَاتِهِ الزُّهْرِ"],["وَمَنْ يُقِمِ الْقُرْآنَ كَالْقِدْحِ فَلْيَكُنْ","مُطِيعًا لِأَمْرِ اللَّهِ فِي السِّرِّ وَالْجَهْرِ"],["أَلَا اعْلَمْ أَخِي أَنَّ الْفَصَاحَةَ زَيَّنَتْ","تِلَاوَةَ تَالٍ أَدْمَنَ الدَّرْسَ لِلذِّكْرِ"],["إِذَا مَا تَلَا التَّالِي أَرَقَّ لِسَانَهُ","وَأَذْهَبَ بِالْإِدْمَانِ عَنْهُ أَذَى الصَّدْرِ"],["فَأَوَّلُ عِلْمِ الذِّكْرِ إِتْقَانُ حِفْظِهِ","وَمَعْرِفَةٌ بِاللَّحْنِ مِنْ فِيكَ إِذْ يَجْرِي"],["فَكُنْ عَارِفًا بِاللَّحْنِ كَيْمَا تُزِيلَهُ","فَمَا لِلَّذِي لَا يَعْرِفُ اللَّحْنَ مِنْ عُذْرِ"],["وَإِنْ أَنْتَ حَقَّقْتَ الْقِرَاءَةَ فَاحْذَرِ الزْـ","ـزِيَادَةَ فِيهَا وَاسْأَلِ الْعَوْنَ ذَا الْقَهْرِ"],["زِنِ الْحَرْفَ لَا تُخْرِجْهُ عَنْ حَدِّ وَزْنِهِ","فَوَزْنُ حُرُوفِ الذِّكْرِ مِنْ أَفْضَلِ الْبِرِّ"],["وَحُكْمُكَ بِالتَّحْقِيقِ إِنْ كُنْتَ آخِذًا","عَلَى أَحَدٍ أَلَّا تَزِيدَ عَلَى عَشْرِ"],["فَبَيِّنْ إِذَنْ مَا يَنْبَغِي أَنْ تُبِينَهُ","وَأَدْغِمْ وَأَخْفِ الْحَرْفَ فِي غَيْرِ مَا عُسْرِ"],["وَإِنَّ الَّذِي تُخْفِيهِ لَيْسَ بِمُدْغَمٍ","وَبَيْنَهُمَا فَرْقٌ فَفَرِّقْهُ بِالْيُسْرِ"],["وَقُلْ إِنَّ تَسْكِينَ الْحُرُوفِ لِجَزْمِهَا","وَتَحْرِيكَهَا لِلرَّفْعِ وَالنَّصْبِ وَالْجَرِّ"],["فَحَرِّكْ وَسَكِّنْ وَاقْطَعَنْ تَارَةً وَصِلْ","وَمَكِّنْ وَمَيِّزْ بَيْنَ مَدِّكَ وَالْقَصْرِ"],["وَمَا الْمَدُّ إِلَّا فِي ثَلَاثَةِ أَحْرُفٍ","تُسَمَّى حُرُوفَ اللِّينِ بَاحَ بِهَا ذِكْرِي"],["هِيَ الْأَلِفُ الْمَعْرُوفُ فِيهَا سُكُونُهَا","وَيَاءٌ وَوَاوٌ يَسْكُنَانِ مَعًا فَادْرِ"],["وَخَفِّفْ وَثَقِّلْ وَاشْدُدِ الْفَكَّ عَامِدًا","وَلَا تُفْرِطَنْ فِي الْفَتْحِ وَالضَّمِّ وَالْكَسْرِ"],["وَمَا كَانَ مَهْمُوزًا فَكُنْ هَامِزًا لَهُ","وَلَا تَهْمِزَنْ مَا كَانَ لَحْنًا لَدَى النَّبْرِ"],["وَإِنْ تَكُ قَبْلَ الْيَاءِ وَالْوَاوِ فَتْحَةٌ","وَبَعْدَهُمَا هَمْزٌ هَمَزْتَ عَلَى قَدْرِ"],["وَرَقِّقْ بَيَانَ الرَّاءِ وَاللَّامِ يَنْذَرِبْ","لِسَانُكَ حَتَّى تَنْظِمَ الْقَوْلَ كَالدُّرِّ"],["وَأَنْعِمْ بَيَانَ الْعَيْنِ وَالْهَاءِ كُلَّمَا","دَرَسْتَ وَكُنْ فِي الدَّرْسِ مُعْتَدِلَ الْأَمْرِ"],["وَقِفْ عِنْدَ إِتْمَامِ الْكَلَامِ مُوَافِقًا","لِمُصْحَفِنَا الْمَتْلُوِّ فِي الْبَرِّ وَالْبَحْرِ"],["وَلَا تُدْغِمَنَّ الْمِيمَ إِنْ جِئْتَ بَعْدَهَا","بِحَرْفٍ سِوَاهَا وَاقْبَلِ الْعِلْمَ بِالشُّكْرِ"],["وَضَمُّكَ قَبْلَ الْوَاوِ كُنْ مُشْبِعًا لَهُ","كَمَا أَشْبَعُوا ﴿إِيَّاكَ نَعْبُدُ﴾ فِي الْمَرِّ"],["وَإِنْ حَرْفُ لِينٍ كَانَ مِنْ قَبْلِ مُدْغَمٍ","كَآخِرِ مَا فِي الْحَمْدِ فَامْدُدْهُ وَاسْتَجْرِ"],["مَدَدْتَ لِأَنَّ السَّاكِنَيْنِ تَلَاقَيَا","فَصَارَ كَتَحْرِيكٍ كَذَا قَالَ ذُو الْخُبْرِ"],["وَأُسْمِي حُرُوفًا سِتَّةً لِتَخُصَّهَا","بِإِظْهَارِ نُونٍ قَبْلَهَا أَبَدَ الدَّهْرِ"],["فَحَاءٌ وَخَاءٌ ثُمَّ هَاءٌ وَهَمْزَةٌ","وَعَيْنٌ وَغَيْنٌ لَيْسَ قَوْلِيَ بِالنُّكْرِ"],["فَهَذِي حُرُوفُ الْحَلْقِ يَخْفَى بَيَانُهَا","فَدُونَكَ بَيِّنْهَا وَلَا تَعْصِيَنْ أَمْرِي"],["وَلَا تَشْدُدِ النُّونَ الَّتِي يُظْهِرُونَهَا","كَقَوْلِكَ ﴿مِنْ خَيْلٍ﴾ لَدَى سُورَةِ الْحَشْرِ"],["وَإِظْهَارُكَ التَّنْوِينَ فَهْوَ قِيَاسُهَا","فَقِسْهُ عَلَيْهَا فُزْتَ بِالْكَاعِبِ الْبِكْرِ"],["وَقَدْ بَقِيَتْ أَشْيَاءُ بَعْدُ لَطِيفَةٌ","يُلَقَّنُهَا بَاغِي التَّعَلُّمِ بِالصَّبْرِ"],["فَلِابْنِ عُبَيْدِ اللَّهِ مُوسَى عَلَى الَّذِي","يُعَلِّمُهُ الْخَيْرَ الدُّعَاءُ لَدَى الْفَجْرِ"],["أَجَابَكَ فِينَا رَبُّنَا وَأَجَابَنَا","أَخِي فِيكَ بِالْغُفْرَانِ مِنْهُ وَبِالنَّصْرِ"]],"secs":{"1":"رائية الخاقاني"}}],"sharh":false};
